VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT;
    PrevEntry : BOOL;
    PrevExit : BOOL;
    CAP : INT := 3;
END_VAR

IF EntrySensor AND NOT PrevEntry THEN
    IF Count < CAP THEN
        Count := Count + 1;
    END_IF;
END_IF;

IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

FullSign := (Count = CAP);

EntryBarrierOpen := EntryReq AND NOT FullSign;

PrevEntry := EntrySensor;
PrevExit := ExitSensor;

