PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
END_VAR
VAR CONSTANT
    CAP : INT := 3;
END_VAR

(* Detect rising edge of EntrySensor and increment Count if not full *)
IF EntrySensor AND NOT PrevEntry THEN
    IF Count < CAP THEN
        Count := Count + 1;
    END_IF;
END_IF;

(* Detect rising edge of ExitSensor and decrement Count if not empty *)
IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

(* Store current sensor states for next scan's edge detection *)
PrevEntry := EntrySensor;
PrevExit := ExitSensor;

(* Assert FullSign when occupancy reaches capacity *)
FullSign := (Count = CAP);

(* Open entry barrier only if a request is present and the garage is not full *)
EntryBarrierOpen := EntryReq AND (Count < CAP);

END_PROGRAM

