    (* Detect rising edge of ExitSensor *)
    IF ExitSensor AND NOT PrevExit THEN
        (* Decrement occupancy if not below zero *)
        IF Count > 0 THEN
            Count := Count - 1;
        END_IF;
    END_IF;

    (* Update previous sensor states for next scan *)
    PrevEntry := EntrySensor;
    PrevExit := ExitSensor;

    (* Assert FullSign if occupancy is at capacity *)
    FullSign := (Count = CAP);

    (* Open entry barrier only if entry is requested and garage is not full *)
    EntryBarrierOpen := EntryReq AND (Count < CAP);

